import json

# Read all definitions verbatim
def get_node(fpath):
    with open(fpath) as f:
        d = json.load(f)
    node = d.get('Data', {})
    if 'Node' in node:
        node = node['Node']
    return node

trigger_def = get_node('/tmp/def-trigger.json')
script_def = get_node('/tmp/def-script.json')
decision_def = get_node('/tmp/def-decision.json')
end_def = get_node('/tmp/def-end.json')
mock_def = get_node('/tmp/def-mock.json')

ixp_node_id = "extractInvoice"
ixp_vendor_field = "VendorName"
ixp_total_field = "TotalAmount"

# Canonical IxP path
ixp_total_path = f"$vars.{ixp_node_id}.output.ExtractionResult.ResultsDocument.Fields.find(f => f.FieldName === '{ixp_total_field}')?.Values?.[0]"
ixp_vendor_path = f"$vars.{ixp_node_id}.output.ExtractionResult.ResultsDocument.Fields.find(f => f.FieldName === '{ixp_vendor_field}')?.Values?.[0]"

# Decision expression: amount > 1000 (no =js: prefix on decision expressions)
decision_expr = f"parseFloat({ixp_total_path} || 0) > 1000"

# Script for HighValueReview
high_value_script = (
    f"const vendor = {ixp_vendor_path} || 'Unknown';\n"
    f"const amount = {ixp_total_path} || '0';\n"
    f"return {{ summary: 'HighValueReview: Invoice from ' + vendor + ' for ' + amount + ' requires manual review.' }};"
)

# Script for AutoApprove
